//! ↩️ Page override inverses prepare the original affected identity and override vector only.
use crate::LayoutMutation;
use semio_s_artifact_layout_layout_model::snapshot::LayoutSnapshot;
use semio_s_artifact_layout_layout_model::PageOverride;
use semio_framework_os_kernel::{RetainedFieldPreparation,RetainedMutationCloseContext};
use semio_framework_value::{RetirementDemand,ValueError,ValueRefusalKind,retained_clone::{RetainedCloneRef,RetainedCloneBinding,RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep,retained_clone_grant_admits}};
use semio_framework_value_factory::vector::FactoryVectorRetirement;
use std::mem::{ManuallyDrop,size_of};
fn fault()->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,"Page override inverse lost original source custody")}
fn fixed()->RetirementDemand{RetirementDemand{copy_bytes:size_of::<LayoutMutation>()*2+256,depth:1,..Default::default()}}
fn nested(mut d:RetirementDemand)->RetirementDemand{d.copy_bytes+=256;d.depth+=1;d}
fn child(g:RetainedCloneGrant)->RetainedCloneGrant{RetainedCloneGrant{maximum_copy_bytes:g.maximum_copy_bytes-256,maximum_depth:g.maximum_depth-1,..g}}
fn receipt(mut p:RetainedCloneProgress)->RetainedCloneProgress{p.copied_bytes+=256;p.copied_items=p.copied_items.max(1);p}
fn refused(e:ValueError)->ValueError{let p=receipt(e.retained_progress());e.with_retained_progress(p)}
/// 🧳️ Only one inverse command and its affected field become newly owned state.
pub struct OverrideInverse{b:Option<RetainedCloneBinding>,at:usize,id:RetainedFieldPreparation<String>,field:RetainedFieldPreparation<Vec<PageOverride>>,rows:ManuallyDrop<Option<Vec<LayoutMutation>>>,retirement:Option<FactoryVectorRetirement<LayoutMutation>>,phase:u8,closing:bool}
impl Default for OverrideInverse{fn default()->Self{Self{b:None,at:0,id:Default::default(),field:Default::default(),rows:ManuallyDrop::new(None),retirement:None,phase:10,closing:false}}}
fn page_id<'a>(b:RetainedCloneRef<'a,LayoutSnapshot>,at:usize)->RetainedCloneRef<'a,String>{b.project(9,|b|&b.pages).project(at,move|p|&p[at]).project(0,|p|&p.id)}
fn overrides<'a>(b:RetainedCloneRef<'a,LayoutSnapshot>,at:usize)->RetainedCloneRef<'a,Vec<PageOverride>>{b.project(9,|b|&b.pages).project(at,move|p|&p[at]).project(6,|p|&p.overrides)}
impl OverrideInverse{
 pub fn ready(&self)->bool{self.phase==5}
 pub fn demand(&self,b:RetainedCloneRef<'_,LayoutSnapshot>,at:usize,body:usize)->Result<RetirementDemand,ValueError>{if self.closing{return Err(fault())}b.check_binding(&self.b)?;if self.b.is_some()&&self.at!=at{return Err(fault())}Ok(match self.phase{10=>nested(b.binding_demand(&self.b)?.unwrap_or_default()),0=>RetirementDemand{capacity_bytes:size_of::<LayoutMutation>(),..fixed()},1=>if self.id.value().is_some(){fixed()}else{nested(self.id.demand(page_id(b,at),body.min(256))?)},2=>{let mut d=nested(self.id.exchange_demand()?);d.copy_bytes+=size_of::<LayoutMutation>()*2;d},3=>if self.field.value().is_some(){fixed()}else{nested(self.field.demand(overrides(b,at),body.min(256))?)},4=>{let mut d=nested(self.field.exchange_demand()?);d.copy_bytes+=size_of::<LayoutMutation>()*2;d},5=>fixed(),_=>return Err(fault())})}
 pub fn advance(&mut self,b:RetainedCloneRef<'_,LayoutSnapshot>,at:usize,body:usize,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{let d=self.demand(b,at,body)?;if !retained_clone_grant_admits(g,d){return Ok(RetainedCloneStep::Progress(Default::default()))}let mut p=RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()};match self.phase{10=>{p=receipt(b.bind(&mut self.b,child(g)).map_err(refused)?.unwrap_or_default());self.at=at;self.phase=0},0=>{self.phase=254;*self.rows=Some(Vec::new());let rows=self.rows.as_mut().unwrap();let admitted=rows.try_reserve_exact(1);p.retained_capacity_bytes=rows.capacity()*size_of::<LayoutMutation>();if admitted.is_err()||p.retained_capacity_bytes>g.maximum_capacity_bytes{return Err(fault().with_retained_progress(p))}self.phase=1},1=>if self.id.value().is_some(){self.phase=2}else{p=receipt(self.id.advance(page_id(b,at),body.min(256),child(g)).map_err(refused)?.progress())},2=>{let(value,paid)=self.id.take(RetainedCloneGrant{maximum_copy_bytes:g.maximum_copy_bytes-256-size_of::<LayoutMutation>()*2,maximum_depth:g.maximum_depth-1,..g}).map_err(refused)?;p=receipt(paid);p.copied_bytes+=size_of::<LayoutMutation>()*2;self.rows.as_mut().unwrap().push(LayoutMutation::SetPageOverrides(crate::set_page_overrides::SetPageOverrides{id:value.ok_or_else(fault)?,overrides:Vec::new()}));self.phase=3},3=>if self.field.value().is_some(){self.phase=4}else{p=receipt(self.field.advance(overrides(b,at),body.min(256),child(g)).map_err(refused)?.progress())},4=>{let(value,paid)=self.field.take(RetainedCloneGrant{maximum_copy_bytes:g.maximum_copy_bytes-256-size_of::<LayoutMutation>()*2,maximum_depth:g.maximum_depth-1,..g}).map_err(refused)?;p=receipt(paid);p.copied_bytes+=size_of::<LayoutMutation>()*2;let LayoutMutation::SetPageOverrides(row)=&mut self.rows.as_mut().unwrap()[0]else{return Err(fault())};row.overrides=value.ok_or_else(fault)?;self.phase=5},5=>return Ok(RetainedCloneStep::Complete(p)),_=>return Err(fault())}Ok(RetainedCloneStep::Progress(p))}
 pub fn take_demand(&self)->RetirementDemand{RetirementDemand{copy_bytes:size_of::<Option<Vec<LayoutMutation>>>()*2,depth:1,..Default::default()}}
 pub fn take(&mut self,g:RetainedCloneGrant)->Result<(Option<Vec<LayoutMutation>>,RetainedCloneProgress),ValueError>{if !self.ready()||self.closing{return Err(fault())}let d=self.take_demand();if !retained_clone_grant_admits(g,d){return Ok((None,Default::default()))}self.phase=6;Ok((self.rows.take(),RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))}
 pub fn begin_close(&mut self){self.closing=true;self.id.begin_close();self.field.begin_close()}
 pub fn close_demand(&self,c:RetainedMutationCloseContext<'_,LayoutMutation>,body:usize)->Result<RetirementDemand,ValueError>{if !self.id.terminal_is_empty(){return self.id.close_demand(body)}if !self.field.terminal_is_empty(){return self.field.close_demand(body)}if self.b.is_some(){return Ok(nested(RetainedCloneBinding::close_demand(&self.b,body.min(256))?))}if let Some(owner)=self.retirement.as_ref(){return if owner.terminal_is_empty(){Ok(RetirementDemand{copy_bytes:size_of::<Option<FactoryVectorRetirement<LayoutMutation>>>()*2,depth:1,..Default::default()})}else{owner.demands(c.mutations,body)}}if self.rows.is_some(){return Ok(FactoryVectorRetirement::<LayoutMutation>::constructor_demand())}Ok(Default::default())}
 pub fn close_step(&mut self,c:RetainedMutationCloseContext<'_,LayoutMutation>,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{if !self.closing{return Err(fault())}let d=self.close_demand(c,g.maximum_copy_bytes)?;if !retained_clone_grant_admits(g,d){return Ok(RetainedCloneStep::Progress(Default::default()))}if !self.id.terminal_is_empty(){return self.id.close_step(g).map(|step|RetainedCloneStep::Progress(step.progress()))}if !self.field.terminal_is_empty(){return self.field.close_step(g).map(|step|RetainedCloneStep::Progress(step.progress()))}if self.b.is_some(){return RetainedCloneBinding::close_one(&mut self.b,child(g)).map(|step|RetainedCloneStep::Progress(receipt(step.progress()))).map_err(refused)}if let Some(owner)=self.retirement.as_mut(){if owner.terminal_is_empty(){self.retirement=None;return Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))}return owner.close_step(c.mutations,g).map(|step|RetainedCloneStep::Progress(step.progress()))}if let Some(rows)=self.rows.take(){match FactoryVectorRetirement::admit(rows,g){Ok((owner,p))=>{self.retirement=Some(owner);return Ok(RetainedCloneStep::Progress(p))},Err((error,rows))=>{*self.rows=Some(rows);return Err(error)}}}Ok(RetainedCloneStep::Complete(Default::default()))}
 pub fn terminal_is_empty(&self)->bool{self.closing&&self.b.is_none()&&self.id.terminal_is_empty()&&self.field.terminal_is_empty()&&self.rows.is_none()&&self.retirement.is_none()}
}
impl Drop for OverrideInverse{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"Page override inverse requires funded original cleanup")}}
